/* ERAVOS runtime — icons.js → window.Icons. Domain-free.
 * Drawn line icons (24 × 24, stroke = currentColor) in place of emoji. A domain adds its drawings and says which thing shows
 * which one (core/icons.gen.js, generated by build/icons.mjs from tools/<d>/icons.json); the canvas adds its own interface glyphs
 * (runtime/icons.gen.js). Anything with no drawing falls back to its emoji, so nothing ever shows empty.
 *   add({ name: '<svg inner markup>' }) · map({ thingId: name })   thingId: a tool id, 'suite:<id>', 'cat:<id>'
 *   key(x) → name | null       x: a name, a thing id, or anything with .id (and .icon as its fallback)
 *   svg(x, o) → markup         node(x, o) → <span class="ic"> (svg, or the fallback text)
 *   html(x, o) → the same as markup, for a UIKit h(..., { html }) · label(x, text, o) → an icon then the text, as markup
 *   tile(x, o) → <span class="ic-tile"> the icon on its accent: o.accent, o.size (px)
 *   decorate(root) — every [data-ic="name"] in it gets its icon in front of its words (the top bar is kept decorated as units add
 *   buttons to it)
 * o: { size (px, default 1em), stroke (default 1.75), fallback, cls } */
(function (global) {
  'use strict';
  const drawings = new Map(), names = new Map();
  function add(o) { Object.keys(o || {}).forEach(k => drawings.set(k, o[k])); }
  function map(o) { Object.keys(o || {}).forEach(k => names.set(k, o[k])); }
  function key(x) {
    if (!x) return null;
    if (typeof x === 'string') return drawings.has(x) ? x : (names.has(x) && drawings.has(names.get(x)) ? names.get(x) : null);
    const n = x.id && names.get(x.id); return n && drawings.has(n) ? n : null;
  }
  const esc = (s) => String(s).replace(/[<>&"]/g, c => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;' }[c]));
  function svg(x, o) {
    o = o || {}; const k = key(x); if (!k) return '';
    const sz = o.size ? o.size + 'px' : '1em';
    return `<svg viewBox="0 0 24 24" width="${sz}" height="${sz}" fill="none" stroke="currentColor" stroke-width="${o.stroke || 1.75}" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false" data-icon="${esc(k)}">${drawings.get(k)}</svg>`;
  }
  function node(x, o) {
    o = o || {}; const el = global.document.createElement('span'); el.className = 'ic' + (o.cls ? ' ' + o.cls : '');
    const s = svg(x, o);
    if (s) el.innerHTML = s; else { el.textContent = o.fallback !== undefined ? o.fallback : (x && typeof x === 'object' ? x.icon || '' : ''); el.classList.add('ic-text'); }
    return el;
  }
  function html(x, o) {
    o = o || {}; const s = svg(x, o); if (s) return `<span class="ic${o.cls ? ' ' + o.cls : ''}">${s}</span>`;
    const t = o.fallback !== undefined ? o.fallback : (x && typeof x === 'object' ? x.icon || '' : ''); return t ? `<span class="ic ic-text">${esc(t)}</span>` : '';
  }
  const label = (x, text, o) => { const i = html(x, o); return !text ? i : (i ? i + ' ' : '') + `<span class="ic-lbl">${esc(text)}</span>`; };
  function tile(x, o) {
    o = o || {}; const el = global.document.createElement('span'); el.className = 'ic-tile' + (o.cls ? ' ' + o.cls : '');
    if (o.accent || (x && x.accent)) el.style.setProperty('--acc', o.accent || x.accent);
    if (o.size) { el.style.width = el.style.height = o.size + 'px'; el.style.fontSize = Math.round(o.size * 0.5) + 'px'; }
    el.appendChild(node(x, { stroke: o.stroke || 1.6, fallback: o.fallback })); return el;
  }
  function decorate(root) {
    (root || global.document).querySelectorAll('[data-ic]').forEach(el => {
      if (el.firstElementChild && el.firstElementChild.classList.contains('ic')) return;
      const k = el.getAttribute('data-ic'); if (!key(k)) return;
      el.insertBefore(node(k), el.firstChild); el.classList.add('has-ic');
    });
  }
  if (global.document) global.document.addEventListener('DOMContentLoaded', () => {
    const tb = global.document.getElementById('topbar'); decorate(global.document);
    if (tb && global.MutationObserver) new global.MutationObserver(() => decorate(tb)).observe(tb, { childList: true, subtree: true });
  });
  global.Icons = { add, map, key, has: (x) => !!key(x), svg, html, label, node, tile, decorate, get size() { return drawings.size; } };
})(typeof window !== 'undefined' ? window : globalThis);
